mapper.select:

WITH target AS MATERIALIZED (
    SELECT id, customer_id, bank_name, masked_account_number, balance
    FROM account WHERE id = #{accountId}
)

SELECT EXISTS (SELECT 1 FROM target) AS account_exists,
       allowed.id AS account_id, allowed.bank_name, allowed.masked_account_number, allowed.balance

FROM (VALUES (1)) AS seed(value)
LEFT JOIN LATERAL (
    SELECT t.id, t.bank_name, t.masked_account_number, t.balance FROM target t
    WHERE



            t.customer_id = #{principalId}



            EXISTS (SELECT 1 FROM access_grant g
                    WHERE g.account_id = t.id AND g.partner_id = #{principalId}
                      AND g.permission = 'ACCOUNT_READ' AND g.revoked_at IS NULL)


        FALSE

) allowed ON TRUE

WITH target AS MATERIALIZED (
    SELECT id, customer_id FROM account WHERE id = #{accountId}
)
SELECT EXISTS (SELECT 1 FROM target) AS account_exists,
       allowed.id AS authorized_account_id, page.id AS transaction_id,
       page.occurred_at, page.amount, page.description

FROM (VALUES (1)) AS seed(value)
LEFT JOIN LATERAL (
    SELECT t.id FROM target t
    WHERE


            t.customer_id = #{principalId}



            EXISTS (SELECT 1 FROM access_grant g
                    WHERE g.account_id = t.id AND g.partner_id = #{principalId}
                      AND g.permission = 'TRANSACTION_READ' AND g.revoked_at IS NULL)

        FALSE

) allowed ON TRUE

LEFT JOIN LATERAL (
    SELECT t.id, t.occurred_at, t.amount, t.description FROM transaction_record t
    WHERE t.account_id = allowed.id

    ORDER BY t.occurred_at DESC, t.id DESC
    LIMIT #{limit} OFFSET #{offset}
) page ON TRUE

ORDER BY page.occurred_at DESC NULLS LAST, page.id DESC

SELECT a.id, a.customer_id, a.bank_name, a.masked_account_number, a.balance, a.created_at
FROM account a
WHERE a.id = #{accountId}
  AND EXISTS (
      SELECT 1 FROM access_grant g
      WHERE g.account_id = a.id AND g.partner_id = #{partnerId}
        AND g.permission = 'ACCOUNT_READ' AND g.revoked_at IS NULL
  )

SELECT t.id, t.account_id, t.occurred_at, t.amount, t.description
FROM transaction_record t JOIN account a ON a.id = t.account_id
WHERE a.id = #{accountId} AND a.customer_id = #{customerId}
ORDER BY t.occurred_at DESC, t.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT t.id, t.account_id, t.occurred_at, t.amount, t.description
FROM transaction_record t
WHERE t.account_id = #{accountId}
  AND EXISTS (
      SELECT 1 FROM access_grant g
      WHERE g.account_id = t.account_id AND g.partner_id = #{partnerId}
        AND g.permission = 'TRANSACTION_READ' AND g.revoked_at IS NULL
  )
ORDER BY t.occurred_at DESC, t.id DESC
LIMIT #{limit} OFFSET #{offset}
